// ==UserScript==
// @name         AWBW YOUR TURN ALERT!!!
// @namespace    http://tampermonkey.net/
// @version      0.1
// @description  Plays an annoying sound when it's your turn
// @author       steve
// @match        https://awbw.amarriner.com/2030.php?games_id=*
// @icon         https://awbw.amarriner.com/terrain/aw1/greenearthcomtower.gif
// @grant        none
// ==/UserScript==

(function () {

    var alerta_sound="data:audio/ogg;base64,";

    var alerta = new Audio(alerta_sound);
    webSocket.addEventListener('message', function (event) {
        if (event.data) {
            var data = JSON.parse(event.data);
            if (data.NextTurn && data.NextTurn.nextPId == viewerPId){
                alerta.play();
            }
        }
    });
})();

